from app.core.resources import display_rows

"""Campuses endpoints and their PostgreSQL queries."""

from fastapi import APIRouter, Depends, HTTPException, Query, Request

from app.core import sql_queries as sql
from app.core.resources import staff_only
from app.core.security import require

from .schemas import CreateRequest, UpdateRequest
from .service import Service

TABLE = "campuses"
router = APIRouter(prefix="/campuses", tags=["Campuses"])


# --- PostgreSQL queries for this screen (generated by tools/generate_module_sql.py from the
# live table definitions; regenerate after schema migrations). Values are bound as %(name)s
# parameters, never formatted into the text; app.core.sql_queries runs these statements and
# keeps custom fields (record_extras) with each record. Table names resolve through the
# connection's search_path (EDUNEXA_DB_SCHEMA).

LIST_SQL = """
SELECT t.code,
       t.institution_code,
       t.name,
       t.address,
       t.city,
       t.state,
       t.postal_code,
       x.data AS extras
FROM campuses AS t
LEFT JOIN record_extras AS x
  ON x.table_name = 'campuses' AND x.record_code = t.code
ORDER BY t.code
"""

GET_SQL = """
SELECT t.code,
       t.institution_code,
       t.name,
       t.address,
       t.city,
       t.state,
       t.postal_code,
       x.data AS extras
FROM campuses AS t
LEFT JOIN record_extras AS x
  ON x.table_name = 'campuses' AND x.record_code = t.code
WHERE t.code = %(code)s
"""

INSERT_SQL = """
INSERT INTO campuses (
    code,
    institution_code,
    name,
    address,
    city,
    state,
    postal_code
)
VALUES (
    %(code)s,
    %(institution_code)s,
    %(name)s,
    %(address)s,
    %(city)s,
    %(state)s,
    %(postal_code)s
)
"""

UPDATE_SQL = """
UPDATE campuses
SET institution_code = %(institution_code)s,
    name = %(name)s,
    address = %(address)s,
    city = %(city)s,
    state = %(state)s,
    postal_code = %(postal_code)s
WHERE code = %(code)s
"""

DELETE_SQL = """
DELETE FROM campuses
WHERE code = %(code)s
"""

REFERENCED_BY_SQL = """
SELECT CASE
    WHEN EXISTS (SELECT 1 FROM admin_mobile_preferences WHERE default_campus_code = %(code)s) THEN 'admin_mobile_preferences'
    WHEN EXISTS (SELECT 1 FROM admission_cycles WHERE campus_code = %(code)s) THEN 'admission_cycles'
    WHEN EXISTS (SELECT 1 FROM admission_enquiries WHERE campus_code = %(code)s) THEN 'admission_enquiries'
    WHEN EXISTS (SELECT 1 FROM announcements WHERE campus_code = %(code)s) THEN 'announcements'
    WHEN EXISTS (SELECT 1 FROM calendar_events WHERE campus_code = %(code)s) THEN 'calendar_events'
    WHEN EXISTS (SELECT 1 FROM departments WHERE campus_code = %(code)s) THEN 'departments'
    WHEN EXISTS (SELECT 1 FROM employees WHERE campus_code = %(code)s) THEN 'employees'
    WHEN EXISTS (SELECT 1 FROM expenses WHERE campus_code = %(code)s) THEN 'expenses'
    WHEN EXISTS (SELECT 1 FROM external_remittances WHERE campus_code = %(code)s) THEN 'external_remittances'
    WHEN EXISTS (SELECT 1 FROM hostels WHERE campus_code = %(code)s) THEN 'hostels'
    WHEN EXISTS (SELECT 1 FROM inventory_items WHERE campus_code = %(code)s) THEN 'inventory_items'
    WHEN EXISTS (SELECT 1 FROM payroll_runs WHERE campus_code = %(code)s) THEN 'payroll_runs'
    WHEN EXISTS (SELECT 1 FROM placement_drives WHERE campus_code = %(code)s) THEN 'placement_drives'
    WHEN EXISTS (SELECT 1 FROM report_export_jobs WHERE campus_code = %(code)s) THEN 'report_export_jobs'
    WHEN EXISTS (SELECT 1 FROM rooms WHERE campus_code = %(code)s) THEN 'rooms'
    WHEN EXISTS (SELECT 1 FROM students WHERE campus_code = %(code)s) THEN 'students'
    WHEN EXISTS (SELECT 1 FROM transport_routes WHERE campus_code = %(code)s) THEN 'transport_routes'
    WHEN EXISTS (SELECT 1 FROM user_roles WHERE campus_code = %(code)s) THEN 'user_roles'
    WHEN EXISTS (SELECT 1 FROM vehicles WHERE campus_code = %(code)s) THEN 'vehicles'
END AS referenced_by
"""
# --- end of generated SQL


def query_list(data):
    return sql.fetch_all(data, TABLE, LIST_SQL)


def query_get(data, code):
    record = sql.fetch_one(data, TABLE, GET_SQL, code)
    if record is None:
        raise HTTPException(404, "Record not found")
    return record


def query_save(data, record):
    return sql.save(data, TABLE, record, INSERT_SQL, UPDATE_SQL)


def query_delete(data, code):
    sql.delete(data, TABLE, DELETE_SQL, code)


def query_referenced_by(data, code):
    return sql.referenced_by(data, TABLE, REFERENCED_BY_SQL, code)


class Queries:
    table = TABLE
    list = staticmethod(query_list)
    get = staticmethod(query_get)
    save = staticmethod(query_save)
    delete = staticmethod(query_delete)
    referenced_by = staticmethod(query_referenced_by)


service = Service(Queries())


@router.get("")
def list_records(
    request: Request,
    offset: int = Query(0, ge=0),
    limit: int = Query(50, ge=1, le=200),
    user=Depends(require(TABLE, "view")),
):
    staff_only(user)
    data = request.app.state.store.snapshot()
    records = display_rows(data, TABLE, query_list(data))
    return {
        "items": records[offset : offset + limit],
        "total": len(records),
        "offset": offset,
        "limit": limit,
    }


@router.get("/{code}")
def get_record(code: str, request: Request, user=Depends(require(TABLE, "view"))):
    staff_only(user)
    return query_get(request.app.state.store.snapshot(), code)


@router.post("", status_code=201)
def create_record(
    body: CreateRequest, request: Request, user=Depends(require(TABLE, "create"))
):
    staff_only(user)
    with request.app.state.store.transaction() as data:
        return service.create(
            data, body.model_dump(mode="json", exclude_unset=True), user["code"]
        )


@router.patch("/{code}")
def update_record(
    code: str,
    body: UpdateRequest,
    request: Request,
    user=Depends(require(TABLE, "edit")),
):
    staff_only(user)
    with request.app.state.store.transaction() as data:
        return service.update(
            data, code, body.model_dump(mode="json", exclude_unset=True), user["code"]
        )


@router.delete("/{code}", status_code=204)
def delete_record(code: str, request: Request, user=Depends(require(TABLE, "delete"))):
    staff_only(user)
    with request.app.state.store.transaction() as data:
        service.delete(data, code, user["code"])
